"""One batch: every public projection arm, shape and fresh seed; no donor drivers."""
import ast,base64,hashlib,json,lzma
from pathlib import Path
H=Path(__file__).resolve().parent;R=H.parents[3];O=H/'out'
source=(O/'source.py').read_text();ref=(R/'problems/muse_bf16_proj/reference.py').read_text();names={'FP32_LAYERS','REL_L2_TOL','ROUTER_TOL','PROBE_TOL','ref_kernel','probe_rows','check_implementation'};checker=(R/'problems/muse_bf16_proj/checks.py').read_text()+'\n'+'\n'.join(ast.get_source_segment(ref,n) for n in ast.parse(ref).body if getattr(n,'name',None) in names or isinstance(n,ast.Assign) and any(getattr(t,'id',None) in names for t in n.targets))
checks=[(R/'problems/muse_decode_layer/nvfp4.py').read_text(),(R/'problems/muse_decode_layer/checks.py').read_text(),(R/'problems/muse_decode_layer/reference.py').read_text().replace('from checks import compare, query_precision_bound, relative_l2','').replace('from nvfp4 import BLOCK, dequantize, random_weights','')]
