payload='LAB_RESOURCES={"compile_s":500,"run_s":330,"output_bytes":13744,"context_poison":"none"}\nimport torch,triton,triton.language as tl,time,types,linecache,hashlib,json,statistics,math,lzma,base64,struct,gc\nfrom torch.utils.cpp_extension import load_inline\nPP_SOURCE=lzma.decompress(base64.b85decode('+repr(base64.b85encode(lzma.compress(source.encode())).decode())+')).decode()\nPP_TASK='+repr(checks)+'\nPP_CHECK='+repr(checker)+'\nPP_GUARD='+repr(guard)+'\n'+(H.parent/'native_boundary/codec.py.inc').read_text()+'\n'+(H/'lab.py.inc').read_text();compile(payload,'<P10 public projection batch>','exec');(O/'public_projection.py').write_text(payload)
(H/'lab_manifest.json').write_text(json.dumps(dict(payload_sha256=hashlib.sha256(payload.encode()).hexdigest(),source_sha256=hashlib.sha256(source.encode()).hexdigest(),base_sha256=json.loads((H/'source_manifest.json').read_text())['base_sha256'],weight_seed=31000311,router_seed=31000313,seeds=[31000319+104729*i for i in range(8)],rounds=4,all_arm_rounds_retained=True,symmetric='palindromic-cohort-v1, rotated forward/reverse, arithmetic mean all rounds',arms=['A','AA','O raw donor','P PDL donor','C exact coded swapAB','N unshipped NF v18'],cells=36),indent=2)+'\n');print(len(payload))
